#!/usr/bin/env bash
set -Eeuo pipefail
set +x
umask 077
MODE="${1:---check}"
[[ "$MODE" == --check || "$MODE" == --apply ]] || exit 2
fail(){ echo "BLOCKED: $*" >&2; exit 1; }
[[ "$(id -u)" == 0 ]] || fail 'Run as root.'
for cmd in python3 git tar base64 sha256sum runuser flock; do command -v "$cmd" >/dev/null || fail "Missing $cmd"; done
VHOST=/www/server/panel/vhost/nginx/bambodia.com.conf
[[ -f "$VHOST" ]] || fail 'Bambodia nginx vhost not found.'
mapfile -t detected < <(python3 - "$VHOST" <<'PYDETECT'
import re,sys
s=open(sys.argv[1]).read()
s=re.sub(r'#[^\n]*','',s)
r=re.findall(r'(?m)^\s*root\s+([^;]+);',s)
v=re.findall(r'enable-php-(\d+)\.conf',s)
if len(set(r))!=1 or len(set(v))!=1: sys.exit(1)
root=r[0].strip().strip('"').rstrip('/')
if not root.endswith('/public'): sys.exit(1)
print(root[:-7]);print('/www/server/php/'+v[0]+'/bin/php')
PYDETECT
)
[[ "${#detected[@]}" == 2 ]] || fail 'Cannot uniquely detect live app/PHP from vhost.'
APP="${detected[0]}"; PHP="${detected[1]}"
[[ -d "$APP" && ! -L "$APP" && -f "$APP/artisan" && -f "$APP/vendor/autoload.php" && -x "$PHP" ]] || fail 'Invalid Laravel runtime.'
[[ ! -f "$APP/storage/framework/down" ]] || fail 'Site already in maintenance mode.'
OWNER="$(stat -c %U "$APP/storage")"
[[ "$OWNER" != root ]] || fail 'Storage must belong to the website account.'
id "$OWNER" >/dev/null
exec 9>/var/lock/bambodia-media-upload.lock
flock -n 9 || fail 'Another media upgrade is running.'
TMP="$(mktemp -d /root/bambodia-media-upload.XXXXXXXX)"
BACKUP=''; CHANGED=0; MAINT=0
artisan(){ (cd "$APP" && runuser -u "$OWNER" -- "$PHP" artisan "$@"); }
cleanup(){
 result=$?; trap - EXIT
 if (( result != 0 && CHANGED == 1 )); then
   echo "Restoring original files from $BACKUP"
   while IFS= read -r file; do rm -f -- "$APP/$file"; done < "$TMP/paths"
   if ! tar -xpf "$BACKUP/files.tar" -C "$APP"; then echo 'ROLLBACK FAILED; site left in maintenance.'; exit 1; fi
   artisan route:clear || true
   artisan view:clear || true
 fi
 if (( MAINT == 1 )); then artisan up || true; fi
 rm -rf -- "$TMP"
 exit "$result"
}
trap cleanup EXIT
cat <<'PATCH64' | base64 -d > "$TMP/change.patch"

PATCH64
echo "ee430722006ddea8c46447bc81c604eb6364b87ffd69c9a0397d251c2749de14  $TMP/change.patch" | sha256sum -c -

cat > "$TMP/paths" <<'PATHS'
app/Http/Controllers/MediaLibraryController.php
public/css/media-upload.css
public/js/media-upload.js
resources/views/media/index.blade.php
resources/views/media/upload.blade.php
routes/web.php
PATHS
mkdir "$TMP/stage"
: > "$TMP/existing"
while IFS= read -r file; do
 [[ "$(realpath -m "$APP/$file")" == "$APP/$file" ]] || fail "Symlink path: $file"
 mkdir -p "$TMP/stage/$(dirname "$file")"
 if [[ -e "$APP/$file" ]]; then
   [[ -f "$APP/$file" ]] || fail "Not a regular file: $file"
   cp -p "$APP/$file" "$TMP/stage/$file"
   echo "$file" >> "$TMP/existing"
 fi
done < "$TMP/paths"
if (cd "$TMP/stage" && git apply --reverse --check "$TMP/change.patch") 2>/dev/null; then
 echo 'ALREADY_INSTALLED'; exit 0
fi
(cd "$TMP/stage" && git apply --check "$TMP/change.patch" && git apply "$TMP/change.patch") || fail 'Live code differs: no live files changed. Send this output for reconciliation.'
"$PHP" -l "$TMP/stage/app/Http/Controllers/MediaLibraryController.php"
"$PHP" -l "$TMP/stage/routes/web.php"
echo "APP=$APP"
echo 'PREFLIGHT=PASS; database migrations=none'
[[ "$MODE" == --apply ]] || exit 0
BACKUP="$(mktemp -d /root/bambodia-media-backup-XXXXXXXX)"
tar -cpf "$BACKUP/files.tar" -C "$APP" -T "$TMP/existing"
tar -tf "$BACKUP/files.tar" >/dev/null
cp "$TMP/paths" "$BACKUP/changed-paths.txt"
cp "$TMP/existing" "$BACKUP/existing-paths.txt"
ENV_HASH="$(sha256sum "$APP/.env")"
artisan down --retry=30
MAINT=1
CHANGED=1
while IFS= read -r file; do
 install -o "$OWNER" -g "$(id -gn "$OWNER")" -m 0644 "$TMP/stage/$file" "$APP/$file"
done < "$TMP/paths"
artisan route:clear
artisan view:clear
artisan view:cache
artisan route:list --path=media-library --json > "$TMP/routes.json"
python3 - "$TMP/routes.json" <<'PYROUTES'
import json,sys
routes=json.load(open(sys.argv[1]))
for name in ['dashboard.media.create','studio.media.create','account.media.create']:
 assert any(r['name']==name for r in routes), name
PYROUTES
[[ "$(sha256sum "$APP/.env")" == "$ENV_HASH" ]] || fail 'Environment changed during installation.'
artisan up
MAINT=0
CHANGED=0
echo "INSTALLED=YES"
echo "BACKUP=$BACKUP"
echo 'Open https://bambodia.com/dashboard/media-library/upload'
echo 'If old PHP code is cached, reload the site PHP service from aaPanel.'
